24:         // The escape check above still precedes any cycle test.
25:         if ((i & 63) == 0) {
26:             if (i == 0) {
27:                 checkpoint_re = z_re;
28:                 checkpoint_im = z_im;
29:             } else {
30:                 ++checkpoint_distance;
31:                 if (std::memcmp(&z_re, &checkpoint_re, sizeof(float)) == 0 &&
